INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-03' FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Clearance model (myDATA) — B2B mandate rolling out through 2026', 'This deep-dive page reflects publicly available guidance and reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. Greece''s domestic B2B mandate was still in its Phase 2 rollout at time of writing — confirm current status directly with AADE before building against it.', 'Greece runs one of the tracker''s more mature clearance systems: myDATA has required real-time reporting of every invoice since 2021, B2G e-invoicing has been fully mandatory since September 2025, and a domestic B2B mandate is now rolling out in two phases through 2026 — Phase 1 (businesses over €1 million revenue) took effect on 2 March 2026 and is already in force; Phase 2 extends the obligation to every remaining business from 1 October 2026.', 'Two related but distinct standards apply depending on the transaction type: EN 16931 via the Greek Peppol CIUS for B2G, and EN 16931-based invoices validated through the myDATA clearance system for B2B — notably, Peppol is not the mandatory exchange route for B2B, unlike B2G.', 'Every invoice, B2G or B2B, is validated by myDATA and assigned a unique registration mark (MARK) and QR code before it has legal effect — a genuine pre-clearance model, not a post-transaction reporting one. B2G invoices then move on to public bodies via accredited Peppol Access Points; B2B invoices move via certified e-invoicing providers, AADE''s free Timologio app, or direct ERP integration through the myDATA REST API.', 'With Phase 1 of the domestic B2B mandate already in force and Phase 2 approaching in October 2026, most businesses'' near-term work is genuinely time-sensitive rather than exploratory — confirming a compliance route, checking which phase applies, and understanding the mandate''s actual scope (domestic and non-EU B2B only; intra-EU B2B remains optional for now).', 'Failure to issue a required e-invoice is treated as non-issuance of the invoice itself — a real, substantial penalty (50% of the VAT that would have resulted), not merely a procedural formality, reflecting the clearance model''s underlying purpose of closing the VAT gap.', 'Greece''s myDATA platform has required real-time invoice and bookkeeping reporting since 2021, assigning every transaction a unique MARK and QR code. B2G e-invoicing became fully mandatory in September 2025 following a phased 2023-2025 rollout. A domestic B2B mandate is now in force: Phase 1 (businesses with revenue over €1 million) took effect 2 March 2026 under an EU derogation (Council Implementing Decision (EU) 2025/502); Phase 2 extends the obligation to all remaining businesses from 1 October 2026, with an adjustment period through year-end. The mandate covers domestic B2B and B2B sales to non-EU entities; intra-EU B2B remains optional. Separately, ViDA''s cross-border B2B e-invoicing and reporting mandate is confirmed EU law from 1 July 2030.', '🇬🇷' FROM countries WHERE name_en = 'Greece';
