INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["B2G format", "EN 16931 via the Greek Peppol CIUS"], ["B2B format", "EN 16931-based, validated through myDATA clearance — Peppol is not the mandatory exchange route"], ["Legal basis", "Law 4972/2022 (B2G); Council Implementing Decision (EU) 2025/502 (B2B derogation)"], ["Validation", "Every invoice receives a MARK (unique registration mark) and QR code from myDATA before it has legal effect"]]', 'The MARK/QR requirement applies uniformly across B2G and B2B — the genuine difference is the transmission channel, not the underlying validation step.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["B2G", "Accredited Peppol Access Point required"], ["B2B", "Certified e-invoicing provider, AADE''s free Timologio app, or direct ERP integration via the myDATA REST API"], ["Oversight body", "AADE — the Independent Authority for Public Revenue"], ["Threshold (Phase 1)", "Annual revenue above €1 million"]]', 'Unlike many peers, Greece offers a genuinely free compliance route (Timologio) alongside certified commercial providers — worth checking before assuming a paid solution is required.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content', '[["Core model", "Full EN 16931 semantic data model"], ["B2B scope", "Domestic transactions and sales to non-EU entities — intra-EU B2B remains optional for now"], ["Archiving", "Standard Greek record-keeping requirement applies"]]', 'The intra-EU carve-out is a genuine nuance worth noting — a Greek business selling to a German counterpart is not yet mandated to e-invoice that specific transaction, even though its domestic and non-EU sales are.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Network model', '[["Model", "Genuine pre-clearance — myDATA validates and MARKs every invoice before it has legal effect"], ["B2G transmission", "Accredited Peppol Access Points to the National Interoperability Center (KED)"], ["B2B transmission", "Certified providers, Timologio, or direct myDATA REST API — not necessarily Peppol"], ["Real-time reporting", "Yes — myDATA has required this since 2021, ahead of the e-invoicing mandate itself"]]', 'Greece''s reporting-first, invoicing-second sequencing is unusual — most clearance countries built the mandate and the reporting system together, while Greece had years of live myDATA reporting data before layering a full e-invoicing mandate on top.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Rollout phases', '[["Phase 1", "2 March 2026 — businesses with revenue over €1 million (in force)"], ["Transition period", "Through 3 May 2026 — graduated enforcement for isolated technical failures"], ["Phase 2", "1 October 2026 — all remaining businesses"], ["Adjustment period", "Through 31 December 2026"]]', 'Phase 1 is already in force as of today — this isn''t a future milestone to plan around, it''s a current, active obligation for businesses above the revenue threshold.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Scope boundaries', '[["Mandatory", "Domestic B2B; B2B sales to non-EU entities"], ["Not yet mandatory", "Intra-EU B2B (remains optional)"], ["Not covered", "B2C transactions — no mandatory B2C e-invoicing framework"], ["EU derogation", "Council Implementing Decision (EU) 2025/502 authorises the domestic mandate ahead of ViDA''s general timeline"]]', 'Businesses should check each counterparty''s location carefully — a Greek company''s obligations differ meaningfully depending on whether a buyer is domestic, in another EU state, or outside the EU.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ Non-issuance penalty', NULL, NULL, 'Failing to issue a required e-invoice is treated in law as non-issuance of the invoice itself, triggering a fine of 50% of the VAT that would have resulted — a substantial, revenue-linked penalty rather than a flat administrative fee.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🕐 Graduated enforcement during transition', NULL, NULL, 'AADE applied graduated enforcement through 3 May 2026 for businesses in Phase 1''s transition period — isolated technical failures didn''t trigger the full penalty framework, though all covered businesses were expected to be fully operational by the window''s end.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🇪🇺 The approaching EU floor', NULL, NULL, 'Regardless of the domestic mandate''s own scope, ViDA''s cross-border requirement is confirmed EU law from 1 July 2030 — every Greek business doing intra-EU B2B trade will eventually need EN 16931-compliant e-invoicing and digital reporting for those specific transactions too.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm which phase applies to your business', 'Phase 1 (revenue over €1 million) is already in force as of 2 March 2026; Phase 2 (all remaining businesses) takes effect 1 October 2026.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose your compliance route', 'A certified commercial e-invoicing provider, AADE''s free Timologio app, or direct ERP integration via the myDATA REST API — all are valid, and Timologio is a genuine no-cost option worth evaluating.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Map your counterparties by location', 'The mandate covers domestic B2B and non-EU B2B sales, but not yet intra-EU B2B — confirm which of your transactions are actually in scope before assuming full coverage is required.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your myDATA MARK/QR generation is correct', 'Every invoice needs a valid MARK and QR code from myDATA before it has legal effect — this has applied since 2021 and remains foundational to the newer B2B mandate.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Greece';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Prepare for the confirmed 2030 cross-border floor regardless', 'Once ViDA''s cross-border requirement takes effect on 1 July 2030, intra-EU B2B transactions will need EN 16931 e-invoicing and digital reporting too, regardless of Greece''s own domestic scope decisions.');
